    },
    {
      "claim": "L5 verapamil records show that verapamil is a P-gp substrate with extensive first-pass metabolism, but also high passive permeability and no significant AUC/Cmax change with elacridar in rats; no threshold-specific F value is provided for verapamil or the query.",
      "card_ids": ["C49", "C50", "C51", "C52", "C55", "C57", "C59", "C60"]
    },
    {
      "claim": "L5 records for isoliensinine, phillyrin, and phyllanthin are structurally unrelated to the query and do not bear on its oral bioavailability.",
      "card_ids": ["C53", "C54", "C56"]
    }
  ],
